-- 003_create_menu_pdfs_bucket_and_policies.sql
-- Create the new storage bucket for PDFs and set bucket‑level limits.
-- Bucket name must match the code: "menu-pdfs".

INSERT INTO storage.buckets (id, name, public, allowed_mime_types, file_size_limit)
VALUES (
  gen_random_uuid(),
  'menu-pdfs',
  true,
  ARRAY['application/pdf']::text[],
  5242880 -- 5 MiB
);

-- Policy for INSERT (with CHECK) – only admins or staff may upload PDFs.
-- Bucket creation (id generated by Supabase UI; we use ON CONFLICT to be safe)
INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
VALUES (gen_random_uuid(), 'menu-pdfs', true, 5242880, ARRAY['application/pdf']::text[])
ON CONFLICT (id) DO NOTHING;

-- Policies on storage.objects for the new bucket (bucket_id = 'menu-pdfs')
CREATE POLICY admin_insert_pdf ON storage.objects
  FOR INSERT TO authenticated
  USING (bucket_id = 'menu-pdfs')
  WITH CHECK (bucket_id = 'menu-pdfs' AND public.is_admin_or_staff());

CREATE POLICY admin_update_pdf ON storage.objects
  FOR UPDATE TO authenticated
  USING (bucket_id = 'menu-pdfs' AND public.is_admin_or_staff())
  WITH CHECK (bucket_id = 'menu-pdfs' AND public.is_admin_or_staff());

CREATE POLICY admin_delete_pdf ON storage.objects
  FOR DELETE TO authenticated
  USING (bucket_id = 'menu-pdfs' AND public.is_admin_or_staff());

-- Optional admin‑only SELECT (required only if Supabase’s remove() needs SELECT)
CREATE POLICY admin_select_pdf ON storage.objects
  FOR SELECT TO authenticated
  USING (bucket_id = 'menu-pdfs' AND public.is_admin_or_staff()); (id, bucket_id, name, type, using, with_check)
VALUES (
  gen_random_uuid(),
  'menu-pdfs',
  'admin_insert_pdf',
  'INSERT',
  'true',
  'public.is_admin_or_staff()'
);

